374	// validateLoaded 对解码后的状态做基本不变量检查，违背即视为损坏。
375	func validateLoaded(fd *fileData) error {
376		switch {
377		case fd.Version != int(fileVersion):
378			return fmt.Errorf("%w: version %d in payload", ErrUnsupportedVersion, fd.Version)
379		case len(fd.Trajectory) == 0:
380			return fmt.Errorf("%w: empty trajectory", ErrCorrupt)
381		}
382		if err := validateConfig(fd.Config); err != nil {
383			// 配置不合法不可能由本版本写出。
384			return fmt.Errorf("%w: %v", ErrCorrupt, err)
385		}
386		// 保存的整条轨迹必须满足与导入时相同的时间规则：从初始位姿起
387		// 时间严格递增，且相邻位姿的真实间隔不超过 MaxInterval（恰好
388		// 等于上限合法）。任何一处相等、倒退或超限都使按时间查询失去
389		// 可靠的先后依据，整份文件按损坏拒绝。间隔按真实差值判断：前
390		// 一时间接近 math.MinInt64 而后一时间为非负时，有符号减法会
391		// 溢出回绕成负数，把超限的巨大缺口放过去；此处已保证递增，真
392		// 实差值落在 [1, 2^64-1]，用无符号减法取精确的数学差值再与上
393		// 限比较（MaxInterval 已校验为正）。
394		for i := 1; i < len(fd.Trajectory); i++ {
395			prev, cur := fd.Trajectory[i-1].Time, fd.Trajectory[i].Time
396			if cur <= prev {
397				return fmt.Errorf("%w: trajectory time at pose %d is not strictly increasing", ErrCorrupt, i)
398			}
399			if uint64(cur)-uint64(prev) > uint64(fd.Config.MaxInterval) {
400				return fmt.Errorf("%w: trajectory interval between poses %d and %d exceeds max interval", ErrCorrupt, i-1, i)
401			}
402		}
403		// 新格式的逐帧依据必须与轨迹（除初始位姿外）一一对应；旧文件缺省
404		// 该字段（解码为 nil），数量为 0。
405		if len(fd.Sources) != 0 && len(fd.Sources) != len(fd.Trajectory)-1 {
406			return fmt.Errorf("%w: frame sources length %d for %d frames", ErrCorrupt, len(fd.Sources), len(fd.Trajectory)-1)
407		}
408		timeAt := func(t int64) bool {
409			for _, p := range fd.Trajectory {
410				if p.Time == t {
411					return true
412				}
413			}
414			return false
415		}
416		seenIDs := make(map[string]struct{}, len(fd.Landmarks))
417		for _, lm := range fd.Landmarks {
418			if lm.ID == "" {
419				return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
420			}
421			if _, dup := seenIDs[lm.ID]; dup {
422				return fmt.Errorf("%w: duplicate landmark %s", ErrCorrupt, lm.ID)
423			}
424			seenIDs[lm.ID] = struct{}{}
425			if len(lm.Occurrences) == 0 {
426				// 兼容旧布局：平铺字段表示第 1 次出现。
427				if lm.Count < 1 || !isFinite(lm.X) || !isFinite(lm.Y) {
428					return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
429				}
430				if lm.LegacyCount < 0 || lm.LegacyCount > lm.Count {
431					return fmt.Errorf("%w: invalid legacy count for landmark %s", ErrCorrupt, lm.ID)
432				}
433				if lm.LegacyCount > 0 && (!isFinite(lm.LegacyMX) || !isFinite(lm.LegacyMY)) {
434					return fmt.Errorf("%w: invalid legacy mean for landmark %s", ErrCorrupt, lm.ID)
435				}
436				continue
437			}
438			activeCount := 0
439			for i, oj := range lm.Occurrences {
440				if oj.Number != i+1 || oj.Count < 1 || !isFinite(oj.X) || !isFinite(oj.Y) {
441					return fmt.Errorf("%w: invalid occurrence for landmark %s", ErrCorrupt, lm.ID)
442				}
443				if oj.LegacyCount < 0 || oj.LegacyCount > oj.Count {
444					return fmt.Errorf("%w: invalid legacy count for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
445				}
446				if oj.LegacyCount > 0 && (!isFinite(oj.LegacyMX) || !isFinite(oj.LegacyMY)) {
447					return fmt.Errorf("%w: invalid legacy mean for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
448				}
449				if oj.Active {
450					activeCount++
451					if i != len(lm.Occurrences)-1 {
452						return fmt.Errorf("%w: active occurrence %d of landmark %s is not the latest", ErrCorrupt, oj.Number, lm.ID)
453					}
454				} else if oj.InvalidReason == "" {
455					return fmt.Errorf("%w: invalidated occurrence %d of landmark %s lacks reason", ErrCorrupt, oj.Number, lm.ID)
456				}
457				// 出现编号即先后次序，各次出现接纳观测的时间范围必须与之
458				// 相容，否则同一观测可能同时属于两次出现（归属校验只确认能
459				// 归入某一次，不排除同时归入两次）。已失效且首次观测时间
460				// 已知的出现，首次观测不能晚于失效；下一次出现的首次观测
461				// 必须严格晚于上一次的失效时间——首次观测与失效两个端点都
462				// 接纳所在时刻的观测，相等即重叠。第 2 次及以后的出现必定
463				// 在上一次失效之后由本包创建，首次观测时间必须已知；只有
464				// 旧文件的第 1 次出现允许未知（无下界，不把零当作起点）。
465				// 这些检查针对保存的出现记录本身，与重叠范围内当前是否有
466				// 观测无关。
467				if !oj.Active && oj.HasFirstSeen && oj.FirstSeenTime > oj.InvalidTime {
468					return fmt.Errorf("%w: occurrence %d of landmark %s first seen at %d after invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, oj.InvalidTime)
469				}
470				if i > 0 {
471					if !oj.HasFirstSeen {
472						return fmt.Errorf("%w: occurrence %d of landmark %s lacks first seen time", ErrCorrupt, oj.Number, lm.ID)
473					}
474					// 上一次出现必已失效（仍有效且非最后一次已在上面拒绝）。
475					if prev := lm.Occurrences[i-1]; oj.FirstSeenTime <= prev.InvalidTime {
476						return fmt.Errorf("%w: occurrence %d of landmark %s starts at %d before previous invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, prev.InvalidTime)
477					}
478				}
479			}
480			if activeCount > 1 {
481				return fmt.Errorf("%w: multiple active occurrences for landmark %s", ErrCorrupt, lm.ID)
482			}
483		}
484		// 校验每条带逐帧依据的观测来源：观测路标必须存在，且所在帧时间必须
485		// 落入该路标某一次出现的时间边界（共享规则见 occurrence.go）。旧出现
486		// 已失效不代表其历史观测无效；同一标识两次出现之间（如 200 失效、
487		// 300 再现时的 250 帧）的观测没有归属，按损坏拒绝。null 帧来自缺少
488		// 逐帧依据的旧地图，其观测不在这里（也无法）核验；旧版平铺路标视为
489		// 一次无边界的有效出现，因此旧地图后来追加的来源帧仍按此规则检查。
490		if len(fd.Sources) != 0 {
491			bounds := make(map[string][]occurrenceWindow, len(fd.Landmarks))
492			for _, lm := range fd.Landmarks {
493				bounds[lm.ID] = occurrenceWindowsOf(lm)
494			}
495			// 归属校验的同时按（路标，出现编号）统计来源观测条数：每条观测
496			// 各算一次，同帧重复观测同一标识不去重，空观测帧不计。null 帧
497			// 缺少逐帧依据，其贡献已固定在出现的旧观测计数中，不在此统计，
498			// 也不能按帧数猜测。
499			tallies := make(map[string]map[int]int, len(fd.Landmarks))
500			for k, src := range fd.Sources {
501				if src == nil {
502					continue // 旧地图帧：无逐帧依据，不要求补齐归属
503				}
504				t := fd.Trajectory[k+1].Time
505				for _, ob := range src.Observations {
506					wins, ok := bounds[ob.ID]
507					if !ok {
508						return fmt.Errorf("%w: observation of unknown landmark %s at frame time %d", ErrCorrupt, ob.ID, t)
509					}
510					num := occurrenceNumberAt(wins, t)
511					if num == 0 {
512						return fmt.Errorf("%w: observation of landmark %s at frame time %d belongs to no occurrence", ErrCorrupt, ob.ID, t)
513					}
514					c := tallies[ob.ID]
515					if c == nil {
516						c = make(map[int]int, 1)
517						tallies[ob.ID] = c
518					}
519					c[num]++
520				}
521			}
522			// 每次出现记录的观测次数必须等于归属该次出现的来源观测条数加上
523			// 该次出现已保存的旧观测贡献：偏多或偏少都是文件损坏。各次出现
524			// 分别核对，不能用另一次出现的观测补足；已失效的旧出现同样核对，
525			// 不因它不再参与区域查询而跳过。回环校正只改位置不改已接受观测
526			// 次数，正常校正后保存的文件仍满足此不变量。
527			for _, lm := range fd.Landmarks {
528				if len(lm.Occurrences) == 0 {
529					// 旧版平铺路标即第 1 次出现。
530					if got := tallies[lm.ID][1] + lm.LegacyCount; got != lm.Count {
531						return fmt.Errorf("%w: landmark %s records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, lm.Count, got)
532					}
533					continue
534				}
535				for _, oj := range lm.Occurrences {
536					if got := tallies[lm.ID][oj.Number] + oj.LegacyCount; got != oj.Count {
537						return fmt.Errorf("%w: landmark %s occurrence %d records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, oj.Number, oj.Count, got)
538					}
539				}
540			}
541		}
542		segIDs := make(map[string]struct{}, len(fd.Segments))
543		for _, sg := range fd.Segments {
544			if sg.ID == "" || sg.Hash == "" {
545				return fmt.Errorf("%w: invalid segment record", ErrCorrupt)
546			}
547			if _, dup := segIDs[sg.ID]; dup {
548				return fmt.Errorf("%w: duplicate segment %s", ErrCorrupt, sg.ID)
549			}
550			segIDs[sg.ID] = struct{}{}
551		}
552		corrIDs := make(map[string]struct{}, len(fd.Corrections))
553		for _, cr := range fd.Corrections {
554			if cr.ID == "" || !timeAt(cr.Anchor) || !timeAt(cr.EndTime) || cr.Anchor > cr.EndTime {
555				return fmt.Errorf("%w: invalid correction record", ErrCorrupt)
556			}
557			if len(cr.Poses) == 0 {
558				return fmt.Errorf("%w: correction %s has no affected poses", ErrCorrupt, cr.ID)
559			}
560			for _, pc := range cr.Poses {
561				if !finitePose(pc.Before) || !finitePose(pc.After) {
562					return fmt.Errorf("%w: correction %s has non-finite pose", ErrCorrupt, cr.ID)
563				}
564			}
565			for _, lc := range cr.Landmarks {
566				if lc.ID == "" {
567					return fmt.Errorf("%w: correction %s has empty landmark id", ErrCorrupt, cr.ID)
568				}
569				if lc.Occurrence < 0 || !isFinite(lc.Before.X) || !isFinite(lc.Before.Y) ||
570					!isFinite(lc.After.X) || !isFinite(lc.After.Y) ||
571					lc.Before.Count < 1 || lc.After.Count < 1 {
572					return fmt.Errorf("%w: correction %s has invalid landmark change", ErrCorrupt, cr.ID)
573				}
574			}
575			if _, dup := corrIDs[cr.ID]; dup {
576				return fmt.Errorf("%w: duplicate correction %s", ErrCorrupt, cr.ID)
577			}
578			corrIDs[cr.ID] = struct{}{}
579		}
580		invalIDs := make(map[string]struct{}, len(fd.Invalidations))
581		for _, iv := range fd.Invalidations {
582			if iv.ID == "" || iv.Reason == "" || iv.Hash == "" || len(iv.Landmarks) == 0 {
583				return fmt.Errorf("%w: invalid invalidation record", ErrCorrupt)
584			}
585			if _, dup := invalIDs[iv.ID]; dup {
586				return fmt.Errorf("%w: duplicate invalidation %s", ErrCorrupt, iv.ID)
587			}
588			invalIDs[iv.ID] = struct{}{}
589			lmSeen := make(map[string]struct{}, len(iv.Landmarks))
590			for _, l := range iv.Landmarks {
591				if l.ID == "" || l.Occurrence < 1 {
592					return fmt.Errorf("%w: invalid invalidation landmark entry", ErrCorrupt)
593				}
594				if _, dup := lmSeen[l.ID]; dup {
595					return fmt.Errorf("%w: invalidation %s lists %s twice", ErrCorrupt, iv.ID, l.ID)
596				}
597				lmSeen[l.ID] = struct{}{}
598			}
599		}
600		return nil
601	}
602	
603	func finitePose(p Pose) bool {
604		return isFinite(p.X) && isFinite(p.Y) && isFinite(p.Heading) && isFinite(p.Variance)
605	}
606	
607	// canonicalCorrectionHash 计算一次校正请求（锚点时间 + 目标位姿）的
608	// 确定性指纹，用于同标识重复提交判定。直接按 IEEE-754 位编码。
609	func canonicalCorrectionHash(anchor int64, tgt CorrectionTarget) string {
610		h := sha256.New()
611		var b [8]byte
612		binary.BigEndian.PutUint64(b[:], uint64(anchor))
613		h.Write(b[:])
614		for _, v := range []float64{tgt.X, tgt.Y, tgt.Heading, tgt.Variance} {
615			binary.BigEndian.PutUint64(b[:], math.Float64bits(v))
616			h.Write(b[:])
617		}
618		return fmt.Sprintf("%x", h.Sum(nil))
619	}
620	
621	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
622	func (m *Map) saveExclusive() error {
623		data, err := encodeFile(m.state)
624		if err != nil {
625			return err
626		}
627		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
628		if err != nil {
629			return err
630		}
631		return writeAndClose(f, data, m.path)
632	}
633	
634	// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
635	func (m *Map) saveReplace() (err error) {
636		data, err := encodeFile(m.state)
637		if err != nil {
638			return err
639		}
640		dir, base := filepath.Split(m.path)
641		if dir == "" {
642			dir = "."
643		}
644		f, err := os.CreateTemp(dir, base+".tmp-*")
645		if err != nil {
646			return err
647		}
648		tmpName := f.Name()
649		// 任何失败路径都尽力清理临时文件。
650		defer func() {
651			if err != nil {
652				_ = os.Remove(tmpName)
653			}
654		}()
655		if err = writeAndClose(f, data, tmpName); err != nil {
656			return err
657		}
658		if err = os.Rename(tmpName, m.path); err != nil {
659			return err
660		}
661		return nil
662	}
663	
664	func writeAndClose(f *os.File, data []byte, name string) (err error) {
665		defer func() {
666			if cerr := f.Close(); err == nil {
667				err = cerr
668			}
669		}()
670		if _, err = f.Write(data); err != nil {
671			return err
672		}
673		if err = f.Sync(); err != nil {
674			return err
675		}
676		return nil
677	}
678	
679	// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
680	// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
681	func canonicalHash(frames []Frame) string {
682		h := sha256.New()
683		var lenBuf [4]byte
684		var numBuf [8]byte
685		putU32 := func(v uint32) {
686			binary.BigEndian.PutUint32(lenBuf[:], v)
687			h.Write(lenBuf[:])
688		}
689		putU64 := func(v uint64) {
690			binary.BigEndian.PutUint64(numBuf[:], v)
691			h.Write(numBuf[:])
692		}
693		putStr := func(s string) {
694			putU32(uint32(len(s)))
695			h.Write([]byte(s))
696		}
697	
698		putU32(uint32(len(frames)))
699		for _, fr := range frames {
700			putU64(uint64(fr.Time))
701			putU64(math.Float64bits(fr.DX))
702			putU64(math.Float64bits(fr.DY))
703			putU64(math.Float64bits(fr.DHeading))
704			putU64(math.Float64bits(fr.MoveVariance))
705			putU32(uint32(len(fr.Observations)))
706			for _, ob := range fr.Observations {
707				putStr(ob.ID)
708				putU64(math.Float64bits(ob.X))
709				putU64(math.Float64bits(ob.Y))
710			}
711		}
712		return fmt.Sprintf("%x", h.Sum(nil))
713	}
714

