1	package posemap
2	
3	import (
4		"encoding/binary"
5		"encoding/json"
6		"errors"
7		"hash/crc32"
8		"os"
9		"path/filepath"
10		"testing"
11	)
12	
13	// readFileData 解码地图文件的 JSON 载荷。
14	func readFileData(t *testing.T, path string) fileData {
15		t.Helper()
16		raw, err := os.ReadFile(path)
17		if err != nil {
18			t.Fatal(err)
19		}
20		var fd fileData
21		if err := json.Unmarshal(raw[headerLen:len(raw)-4], &fd); err != nil {
22			t.Fatal(err)
23		}
24		return fd
25	}
26	
27	// writeFileDataRaw 用（可能被篡改的）fileData 重新组装完整文件并重算 CRC。
28	func writeFileDataRaw(t *testing.T, path string, fd *fileData) {
29		t.Helper()
30		payload, err := json.Marshal(fd)
31		if err != nil {
32			t.Fatal(err)
33		}
34		out := make([]byte, headerLen+len(payload)+4)
35		copy(out[0:8], fileMagic)
36		binary.BigEndian.PutUint16(out[8:10], fileVersion)
37		binary.BigEndian.PutUint32(out[10:14], uint32(len(payload)))
38		copy(out[headerLen:], payload)
39		binary.BigEndian.PutUint32(out[len(out)-4:], crc32.ChecksumIEEE(out[:len(out)-4]))
40		if err := os.WriteFile(path, out, 0o644); err != nil {
41			t.Fatal(err)
42		}
43	}
44	
45	// buildOccurrenceMap 构造含同一路标两次出现的地图：L 在 t=100、200 被
46	// 观测，t=200 失效，t=300 再次被观测。
47	func buildOccurrenceMap(t *testing.T, path string) {
48		t.Helper()
49		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
50		m, err := Create(path, cfg)
51		if err != nil {
52			t.Fatal(err)
53		}
54		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
55			{Time: 100, DX: 1, Observations: []Observation{{ID: "L"}}},
56			{Time: 200, DX: 1, Observations: []Observation{{ID: "L"}}},
57		}}); err != nil {
58			t.Fatal(err)
59		}
60		if _, err := m.Invalidate(Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"L"}}); err != nil {
61			t.Fatal(err)
62		}
63		if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
64			{Time: 300, DX: 1, Observations: []Observation{{ID: "L"}}},
65		}}); err != nil {
66			t.Fatal(err)
67		}
68		if err := m.Close(); err != nil {
69			t.Fatal(err)
70		}
71	}
72	
73	// 正常文件：失效端点（200）属于已失效的第一次出现，再现端点（300）属于
74	// 第二次出现，打开成功且记录原样保留。
75	func TestOpenObservationOwnershipValid(t *testing.T) {
76		path := filepath.Join(t.TempDir(), "m.pose")
77		buildOccurrenceMap(t, path)
78	
79		m, err := Open(path)
80		if err != nil {
81			t.Fatalf("open: %v", err)
82		}
83		defer m.Close()
84		h, err := m.LandmarkAppearances("L")
85		if err != nil {
86			t.Fatal(err)
87		}
88		if len(h.Appearances) != 2 {
89			t.Fatalf("appearances = %+v", h.Appearances)
90		}
91		a1, a2 := h.Appearances[0], h.Appearances[1]
92		if a1.Active || a1.FirstSeenTime != 100 || a1.InvalidTime != 200 || a1.Landmark.Count != 2 {
93			t.Fatalf("occ1 = %+v", a1)
94		}
95		if !a2.Active || a2.FirstSeenTime != 300 || a2.Landmark.Count != 1 {
96			t.Fatalf("occ2 = %+v", a2)
97		}
98		// 查询行为不变。
99		if p, err := m.PoseAt(250); err != nil || p.Time != 200 {
100			t.Fatalf("PoseAt(250) = %+v %v", p, err)
101		}
102		if cur, err := m.CurrentPose(); err != nil || cur.Time != 300 {
103			t.Fatalf("CurrentPose = %+v %v", cur, err)
104		}
105	}
106	
107	// 逐帧观测指向不存在的路标：打开即报 ErrCorrupt，不返回地图对象。
108	// 拒绝时不改写原文件（另见 TestOpenRejectionLeavesFileUntouched）。
109	func TestOpenRejectsUnknownLandmarkObservation(t *testing.T) {
110		path := filepath.Join(t.TempDir(), "m.pose")
111		buildOccurrenceMap(t, path)
112		fd := readFileData(t, path)
113		fd.Sources[0].Observations[0].ID = "GHOST"
114		writeFileDataRaw(t, path, &fd)
115	
116		m, err := Open(path)
117		if !errors.Is(err, ErrCorrupt) {
118			t.Fatalf("err = %v, want ErrCorrupt", err)
119		}
120		if m != nil {
121			t.Fatalf("Open returned usable map: %v", m)
122		}
123	}
124	
125	// Open 拒绝后原文件内容必须保持不变。
126	func TestOpenRejectionLeavesFileUntouched(t *testing.T) {
127		path := filepath.Join(t.TempDir(), "m.pose")
128		buildOccurrenceMap(t, path)
129		fd := readFileData(t, path)
130		fd.Sources[1].Observations[0].ID = "GHOST"
131		writeFileDataRaw(t, path, &fd)
132		saved, err := os.ReadFile(path)
133		if err != nil {
134			t.Fatal(err)
135		}
136		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
137			t.Fatalf("err = %v, want ErrCorrupt, map=%v", err, m)
138		}
139		got, err := os.ReadFile(path)
140		if err != nil {
141			t.Fatal(err)
142		}
143		if string(got) != string(saved) {
144			t.Fatal("Open modified the rejected file")
145		}
146	}
147	
148	// 观测落在两次出现之间（200 失效、300 再现时的 250 帧）：不能因为之后
149	// 存在有效出现就划给第二次出现，按损坏拒绝。
150	func TestOpenRejectsObservationBetweenOccurrences(t *testing.T) {
151		path := filepath.Join(t.TempDir(), "m.pose")
152		buildOccurrenceMap(t, path)
153		fd := readFileData(t, path)
154		// 把最后一帧时间从 300 改为 250：该帧仍观测 L，但 occ1 已于 200
155		// 失效、occ2 首次观测在 300，250 没有归属。
156		fd.Trajectory[3].Time = 250
157		writeFileDataRaw(t, path, &fd)
158	
159		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
160			t.Fatalf("gap observation: err = %v, want ErrCorrupt, map=%v", err, m)
161		}
162	}
163	
164	// 观测早于某次出现的首次观测时间，且没有更早的出现可以包含它：损坏。
165	func TestOpenRejectsObservationBeforeFirstSeen(t *testing.T) {
166		path := filepath.Join(t.TempDir(), "m.pose")
167		buildOccurrenceMap(t, path)
168		fd := readFileData(t, path)
169		// 第一次出现首次观测改为 150：t=100 的观测失去归属。
170		fd.Landmarks[0].Occurrences[0].FirstSeenTime = 150
171		writeFileDataRaw(t, path, &fd)
172	
173		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
174			t.Fatalf("pre-first-seen observation: err = %v, want ErrCorrupt, map=%v", err, m)
175		}
176	}
177	
178	// 只检查当前有效路标会误杀正常保存的失效历史；这里失效出现的区间内
179	// （含失效端点）观测必须被接受。
180	func TestOpenChecksInactiveOccurrences(t *testing.T) {
181		path := filepath.Join(t.TempDir(), "m.pose")
182		buildOccurrenceMap(t, path)
183		fd := readFileData(t, path)
184		// 直接确认被检查的观测结构：t=200 帧的 L 观测属于已失效的第一次出现。
185		var frame200 int64 = 200
186		found := false
187		for _, ob := range fd.Sources[1].Observations {
188			if ob.ID == "L" {
189				found = true
190			}
191		}
192		if !found || fd.Trajectory[2].Time != frame200 {
193			t.Fatalf("test setup wrong: %+v", fd.Sources[1])
194		}
195		// 不做任何篡改：正常文件必须打开成功（若只查有效出现，该观测会被误拒）。
196		m, err := Open(path)
197		if err != nil {
198			t.Fatalf("inactive occurrence history rejected: %v", err)
199		}
200		m.Close()
201	}
202	
203	// 旧地图兼容：null 来源帧不要求补齐归属；但后来追加的、确实带来源的帧
204	// 仍需检查归属。
205	func TestOpenLegacySourcesStillChecked(t *testing.T) {
206		path := filepath.Join(t.TempDir(), "m.pose")
207		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
208		m, err := Create(path, cfg)
209		if err != nil {
