211		}
212		if _, err := m.ImportSegment(Segment{ID: "old", Frames: []Frame{
213			{Time: 100, DX: 1, Observations: []Observation{{ID: "K"}}},
214			{Time: 200, DX: 1, Observations: []Observation{{ID: "K"}}},
215		}}); err != nil {
216			t.Fatal(err)
217		}
218		writeLegacyV1File(t, path, m.state)
219		m.Close()
220	
221		// 纯旧文件可以打开。
222		m2, err := Open(path)
223		if err != nil {
224			t.Fatalf("open legacy: %v", err)
225		}
226		// 旧地图上追加带来源的新帧：t=300 观测 K（旧路标无起始边界，接受）。
227		if _, err := m2.ImportSegment(Segment{ID: "new", Frames: []Frame{
228			{Time: 300, DX: 0.5, Observations: []Observation{{ID: "K"}}},
229		}}); err != nil {
230			t.Fatal(err)
231		}
232		if err := m2.Close(); err != nil {
233			t.Fatal(err)
234		}
235		m3, err := Open(path)
236		if err != nil {
237			t.Fatalf("reopen mixed legacy/new file: %v", err)
238		}
239		m3.Close()
240	
241		// 篡改追加帧的观测为未知路标：旧帧为 null 也不能掩盖新帧的矛盾。
242		fd := readFileData(t, path)
243		if len(fd.Sources) != 3 || fd.Sources[0] != nil || fd.Sources[2] == nil {
244			t.Fatalf("unexpected sources layout: %+v", fd.Sources)
245		}
246		fd.Sources[2].Observations[0].ID = "ZZZ"
247		writeFileDataRaw(t, path, &fd)
248		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
249			t.Fatalf("appended bad source: err = %v, want ErrCorrupt, map=%v", err, m)
250		}
251	}
