1	package posemap
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"testing"
8	)
9	
10	// 第一次出现的失效时间（350）晚于第二次出现的首次观测（300）：两次出现的
11	// 时间区间重叠，300 时刻的观测同时被两次出现接纳。即使格式与校验值正确、
12	// 重叠范围内的观测暂时能归入某一次，打开也必须按 ErrCorrupt 拒绝，不返回
13	// 可用地图对象，且原文件内容不变。
14	func TestOpenRejectsOverlappingOccurrences(t *testing.T) {
15		path := filepath.Join(t.TempDir(), "m.pose")
16		buildOccurrenceMap(t, path)
17		fd := readFileData(t, path)
18		fd.Landmarks[0].Occurrences[0].InvalidTime = 350
19		writeFileDataRaw(t, path, &fd)
20		saved, err := os.ReadFile(path)
21		if err != nil {
22			t.Fatal(err)
23		}
24	
25		m, err := Open(path)
26		if !errors.Is(err, ErrCorrupt) {
27			t.Fatalf("overlapping occurrences: err = %v, want ErrCorrupt", err)
28		}
29		if m != nil {
30			t.Fatalf("Open returned usable map: %v", m)
31		}
32		got, err := os.ReadFile(path)
33		if err != nil {
34			t.Fatal(err)
35		}
36		if string(got) != string(saved) {
37			t.Fatal("Open modified the rejected file")
38		}
39	}
40	
41	// 上一次失效时间与下一次首次观测时间相等（都是 300）也属于重叠：两个
42	// 端点都接纳所在时刻的观测，必须拒绝。
43	func TestOpenRejectsTouchingOccurrenceEndpoints(t *testing.T) {
44		path := filepath.Join(t.TempDir(), "m.pose")
45		buildOccurrenceMap(t, path)
46		fd := readFileData(t, path)
47		fd.Landmarks[0].Occurrences[0].InvalidTime = 300
48		writeFileDataRaw(t, path, &fd)
49	
50		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
51			t.Fatalf("touching endpoints: err = %v, want ErrCorrupt, map=%v", err, m)
52		}
53	}
54	
55	// 单次出现内部首次观测时间晚于失效时间（记录本身自相矛盾）：拒绝。这里
56	// 同时去掉逐帧观测，确保拒绝只由出现记录的时间关系触发，而非观测归属。
57	func TestOpenRejectsFirstSeenAfterInvalidation(t *testing.T) {
58		path := filepath.Join(t.TempDir(), "m.pose")
59		buildOccurrenceMap(t, path)
60		fd := readFileData(t, path)
61		fd.Landmarks[0].Occurrences[0].FirstSeenTime = 250 // 失效时间为 200
62		fd.Sources[0].Observations = nil
63		fd.Sources[1].Observations = nil
64		writeFileDataRaw(t, path, &fd)
65	
66		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
67			t.Fatalf("first seen after invalidation: err = %v, want ErrCorrupt, map=%v", err, m)
68		}
69	}
70	
71	// 第二次出现的首次观测时间未知：只有旧文件的第 1 次出现允许未知，第 2 次
72	// 及以后必定在上一次失效后由本包创建，未知即损坏。
73	func TestOpenRejectsLaterOccurrenceWithoutFirstSeen(t *testing.T) {
74		path := filepath.Join(t.TempDir(), "m.pose")
75		buildOccurrenceMap(t, path)
76		fd := readFileData(t, path)
77		fd.Landmarks[0].Occurrences[1].HasFirstSeen = false
78		writeFileDataRaw(t, path, &fd)
79	
80		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
81			t.Fatalf("later occurrence without first seen: err = %v, want ErrCorrupt, map=%v", err, m)
82		}
83	}
84	
85	// 旧地图兼容：第 1 次出现首次观测时间未知（缺少逐帧来源）保留未知含义，
86	// 失效（200）后再出现（300）仍遵守时间次序，文件正常打开且记录原样保留。
